<script setup lang="ts">
import {computed,ref,watchPostEffect} from 'vue';import {ui} from '../state/device';import {t} from '../state/appearance';
import {httpBackendName,jsonBackendName} from '../contracts';
import {project} from '@project';import {defaultPlatform} from '../project';
const platform={...defaultPlatform,...project.platform};
const container=ref<HTMLElement|null>(null),availableWidth=ref(0);
watchPostEffect(cleanup=>{if(!container.value)return;const observer=new ResizeObserver(entries=>{availableWidth.value=entries[0].contentRect.width;});observer.observe(container.value);cleanup(()=>observer.disconnect());});
const columnCount=computed(()=>availableWidth.value>=1500?4:availableWidth.value>=1080?3:1);
const headings:Record<string,[string,string]>={hardware:['Оборудование','Hardware'],flash_memory:['Flash и RAM','Flash and RAM'],mac_addresses:['MAC-адреса','MAC addresses'],network:['Сеть','Network'],board:['Плата и периферия','Board and peripherals'],build:['Сборка','Build']};
const labels:Record<string,[string,string]>={
 chip_model:['Чип','Chip'],boot_id:['Boot ID','Boot ID'],architecture:['Архитектура','Architecture'],cpu_mhz:['CPU, МГц','CPU, MHz'],crystal_mhz:['Кварц, МГц','Crystal, MHz'],apb_mhz:['APB, МГц','APB, MHz'],revision_major:['Ревизия, major','Revision, major'],revision_minor:['Ревизия, minor','Revision, minor'],cores:['Ядер CPU','CPU cores'],wifi_24ghz:['Wi-Fi 2,4 ГГц','Wi-Fi 2.4 GHz'],wifi_6:['Wi-Fi 6','Wi-Fi 6'],bluetooth_le:['Bluetooth LE','Bluetooth LE'],bluetooth_classic:['Bluetooth Classic','Bluetooth Classic'],ieee802154:['IEEE 802.15.4','IEEE 802.15.4'],usb_serial_jtag:['USB Serial/JTAG','USB Serial/JTAG'],hp_sram_bytes:['HP SRAM','HP SRAM'],lp_sram_bytes:['LP SRAM','LP SRAM'],
 flash_bytes:['Физическая flash','Physical flash'],flash_jedec_id:['Flash JEDEC ID','Flash JEDEC ID'],embedded_flash:['Flash в корпусе','Embedded flash'],heap_internal_bytes:['RAM в heap','Internal heap'],heap_dma_bytes:['DMA-доступная RAM','DMA-capable RAM'],psram_bytes:['PSRAM','PSRAM'],app_partition:['Раздел приложения','Application partition'],app_partition_bytes:['Размер раздела','Partition size'],
 factory_mac:['Заводской eFuse','Factory eFuse'],custom_mac:['eFuse пользователя','Custom eFuse'],base_mac:['Базовый MAC','Base MAC'],wifi_sta_mac:['Wi-Fi STA','Wi-Fi STA'],wifi_ap_mac:['Wi-Fi SoftAP','Wi-Fi SoftAP'],bluetooth_mac:['Bluetooth','Bluetooth'],ethernet_mac:['Ethernet MAC','Ethernet MAC'],ieee802154_eui64:['802.15.4 EUI-64','802.15.4 EUI-64'],
 wifi_connected:['Wi-Fi подключён','Wi-Fi connected'],wifi_mode:['Режим Wi-Fi','Wi-Fi mode'],ipv4:['IPv4','IPv4'],netmask:['Маска','Netmask'],gateway:['Шлюз','Gateway'],ssid:['SSID','SSID'],ap_bssid:['BSSID точки доступа','Access point BSSID'],channel:['Канал','Channel'],rssi_dbm:['RSSI, dBm','RSSI, dBm'],wifi_auth_mode:['Wi-Fi auth mode','Wi-Fi auth mode'],
 rgb_ready:['Драйвер RGB готов','RGB driver ready'],board_led_ready:['Индикатор платы готов','Board LED ready'],lcd_interface:['Интерфейс LCD','LCD interface'],lcd_ready:['LCD готов','LCD ready'],backlight_enabled:['Подсветка включена','Backlight enabled'],touch_controller:['Контроллер сенсора','Touch controller'],renderer:['Рендерер','Renderer'],framebuffers:['Буферов кадра','Framebuffers'],
 lcd_controller:['Контроллер LCD','LCD controller'],lcd_resolution:['Разрешение LCD','LCD resolution'],lcd_spi_ready:['Вывод LCD по SPI','LCD SPI output'],lcd_visual_status:['Изображение LCD','LCD visual check'],backlight_percent:['Подсветка, %','Backlight, %'],rgb_count:['RGB-светодиодов','RGB LEDs'],rgb_gpio:['GPIO светодиода','LED GPIO'],rgb_order:['Порядок RGB','RGB byte order'],rgb_driver:['Драйвер RGB','RGB driver'],sd_slot:['Слот microSD','microSD slot'],sd_mounted:['SD смонтирована','SD mounted'],touch:['Сенсорный экран','Touchscreen'],ble_started:['BLE запущен','BLE started'],
 project:['Проект','Project'],version:['Версия','Version'],idf_version:[platform.sdkLabel,platform.sdkLabel],http_backend:['HTTP / WS / SSE','HTTP / WS / SSE'],json_backend:['JSON-библиотека MCP','MCP JSON library'],mcp_enabled:['MCP включён','MCP enabled'],json_workspace_bytes:['JSON: рабочая область','JSON: workspace'],mcp_input_bytes:['MCP: лимит запроса','MCP: request limit'],mcp_output_bytes:['MCP: буфер ответа','MCP: response buffer'],build_date:['Дата сборки','Build date'],build_time:['Время сборки','Build time'],secure_version:['Secure version','Secure version'],elf_sha256:['ELF SHA-256','ELF SHA-256'],reset_reason:['Причина reset, код','Reset reason code']
};
Object.assign(labels,platform.detailLabels);
// The firmware envelope is authoritative; missing backend metadata stays unknown on older demos.
const groups=computed(()=>Object.entries(ui.info?.details??{}).map(([id,fields])=>({id,title:t(...(headings[id]??[id,id])),rows:Object.entries(id==='build'?{...fields,idf_version:ui.info?.firmware.idf_version??null,http_backend:ui.info?.firmware.http_backend??null,json_backend:ui.info?.firmware.json_backend??null,mcp_enabled:ui.info?.firmware.mcp_enabled??null,json_workspace_bytes:ui.info?.firmware.json_workspace_bytes??null,mcp_input_bytes:ui.info?.firmware.mcp_input_bytes??null,mcp_output_bytes:ui.info?.firmware.mcp_output_bytes??null,boot_id:ui.boot}:id==='network'?{...fields,rssi_dbm:ui.summary?.rssi_dbm??null,wifi_connected:ui.summary?.network_status==='connected'}:fields).map(([key,value])=>({key,label:t(...(labels[key]??[key,key])),value}))})));
const columns=computed(()=>{const result:Array<typeof groups.value>=Array.from({length:columnCount.value},()=>[]);const heights=Array(columnCount.value).fill(0);for(const group of [...groups.value].sort((a,b)=>b.rows.length-a.rows.length)){const index=heights.indexOf(Math.min(...heights));result[index].push(group);heights[index]+=group.rows.length+2;}return result;});
function format(key:string,value:string|number|boolean|null):string{
 if(value===null)return '—';if(typeof value==='boolean')return value?t('Да','Yes'):t('Нет','No');
 if(typeof value==='number')return key.endsWith('_bytes')?(value/1024).toLocaleString(t('ru-RU','en-US'),{maximumFractionDigits:1})+' '+t('КиБ','KiB'):value.toLocaleString(t('ru-RU','en-US'));
 if(key==='http_backend')return httpBackendName(value==='tcp'||value==='idf_httpd'?value:undefined);
 if(key==='json_backend')return jsonBackendName(value);
 if(value==='unverified')return t('Не проверено','Unverified');return value||'—';
}
</script>
<template><div v-if="groups.length" ref="container" :style="{'--info-columns':columnCount}" class="device-detail-groups" data-testid="device-details"><div v-for="(column,index) in columns" :key="index" class="device-detail-column"><section v-for="group in column" :key="group.id" class="panel" :data-detail-group="group.id"><div class="panel-head"><h2>{{group.title}}</h2></div><div class="table-wrap"><table class="device-detail-table"><colgroup><col class="device-detail-label"/><col/></colgroup><tbody><tr v-for="row in group.rows" :key="row.key"><th scope="row">{{row.label}}</th><td :class="{mono:group.id==='mac_addresses'||row.key==='elf_sha256'||row.key==='ap_bssid'}" :data-field="row.key" :data-tooltip="row.value===null?t('Не предоставлено или не поддерживается','Not provided or unsupported'):String(row.value)">{{format(row.key,row.value)}}</td></tr></tbody></table></div></section></div></div></template>

